# Catalog inputs for the Chicago 13-feature model.
# Return paths so large geospatial tables are opened only by the feature code that needs them.
# Parquet: pandas/geopandas read_parquet; GeoJSON: geopandas read_file;
# CSV: pandas read_csv; CTA columns are strings to preserve IDs and GTFS times.
return {
    'street_centerlines': curio_dataset_path("data.cityofchicago.street-center-lines"),
    'overture_segments': curio_dataset_path("data.overture.transportation-segments-chicago"),
    'overture_connectors': curio_dataset_path("data.overture.transportation-connectors-chicago"),
}

