"""Prepare compact WGS84 geometry and fields for the interactive map."""


districts = arg.copy()
required = {"district_id", "district_name", "distance", "rank", "is_reference", "is_top_10", "geometry"}
missing = sorted(required - set(districts.columns))
if missing:
    raise ValueError(f"Map fields are missing: {missing}")
mapped = districts[list(required)].to_crs(4326)
mapped.__dict__["metadata"] = {"name": "sp_pca5_similarity"}
return mapped

