{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "title": "Interactive PCA-5 distance to Br\u00e1s \u2014 click a district",
  "width": 620,
  "height": 620,
  "params": [
    {
      "name": "district_pick",
      "select": {
        "type": "point",
        "on": "click",
        "clear": "dblclick"
      }
    }
  ],
  "projection": {
    "type": "mercator"
  },
  "mark": {
    "type": "geoshape",
    "stroke": "white",
    "strokeWidth": 0.6
  },
  "encoding": {
    "color": {
      "field": "distance",
      "type": "quantitative",
      "scale": {
        "scheme": "viridis",
        "reverse": true
      },
      "title": "PC1\u2013PC5 distance"
    },
    "opacity": {
      "condition": [
        {
          "param": "district_pick",
          "value": 1
        },
        {
          "test": "datum.is_reference || datum.is_top_10",
          "value": 0.95
        }
      ],
      "value": 0.62
    },
    "stroke": {
      "condition": [
        {
          "param": "district_pick",
          "value": "#d62728"
        },
        {
          "test": "datum.is_reference",
          "value": "#d62728"
        }
      ],
      "value": "white"
    },
    "strokeWidth": {
      "condition": [
        {
          "param": "district_pick",
          "value": 3
        },
        {
          "test": "datum.is_reference",
          "value": 3
        }
      ],
      "value": 0.6
    },
    "tooltip": [
      {
        "field": "district_name",
        "title": "District"
      },
      {
        "field": "district_id",
        "title": "ID"
      },
      {
        "field": "rank"
      },
      {
        "field": "distance",
        "format": ".6f"
      }
    ]
  }
}

