{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "title": "PCA cumulative explained variance \u2014 five dimensions selected",
  "width": 510,
  "height": 260,
  "layer": [
    {
      "mark": {
        "type": "line",
        "point": true
      },
      "encoding": {
        "x": {
          "field": "component",
          "type": "quantitative",
          "title": "Components retained"
        },
        "y": {
          "field": "cumulative_variance",
          "type": "quantitative",
          "scale": {
            "domain": [
              0,
              1
            ]
          },
          "title": "Cumulative variance"
        },
        "tooltip": [
          {
            "field": "component"
          },
          {
            "field": "cumulative_variance",
            "format": ".2%"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "rule",
        "color": "#d62728",
        "strokeDash": [
          6,
          4
        ]
      },
      "encoding": {
        "y": {
          "datum": 0.9
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum.selected"
        }
      ],
      "mark": {
        "type": "point",
        "filled": true,
        "size": 150,
        "color": "#d62728"
      },
      "encoding": {
        "x": {
          "field": "component",
          "type": "quantitative"
        },
        "y": {
          "field": "cumulative_variance",
          "type": "quantitative"
        }
      }
    }
  ]
}

